const rows = [
  ["Mầm qua đất nâu","THUẬN","Mầm non đội đất đón mưa đầu\nRễ nhỏ âm thầm bám thật sâu\nChớ vội đòi cành vươn bóng rộng\nChăm ngày, lá biếc sẽ xanh lâu","Khởi đầu thuận khi người hỏi chấp nhận học từ nền tảng và chăm việc nhỏ.","Mầm non","Năng lực mới còn mong manh nhưng có sức sống nếu được chăm đều.","Đừng xem tín hiệu ban đầu là bảo đảm thành công.","Chọn một kỹ năng nền tảng và luyện đều trong tháng tới.","khởi đầu","Đọc quẻ như lời nhắc nuôi dưỡng bước đầu, không thúc ép kết quả sớm."],
  ["Bến đợi con nước","BÌNH","Con nước chưa lên, thuyền nằm bến\nMái chèo hong nắng cạnh hàng dừa\nNgười biết xem dòng không trách sóng\nĐợi đúng con triều, nhẹ mái đưa","Thời điểm chưa thuận để tiến mạnh; quan sát điều kiện và chuẩn bị sẽ hữu ích hơn nóng vội.","Mái chèo bên bến","Khả năng hành động đã có, còn thời cơ cần được đánh giá.","Chờ đợi không đồng nghĩa trì hoãn vô thời hạn.","Đặt mốc xem xét lại và liệt kê điều kiện cần trước khi khởi hành.","thời điểm","Nhấn vào sự chủ động trong lúc chờ và một mốc quyết định rõ ràng."],
  ["Lối quanh sườn núi","CẨN TRỌNG","Đường thẳng khuất sau triền đá cao\nLối vòng đưa bước khỏi vực sâu\nChậm một khúc quanh không mất đích\nCố lao đường tắt dễ thương đau","Lựa chọn an toàn và linh hoạt đáng giá hơn tiến độ nhanh khi rủi ro chưa rõ.","Lối vòng qua triền đá","Một đường đi dài hơn có thể tránh nguy cơ mà mắt thường chưa thấy.","Không đánh đồng sự thận trọng với thất bại.","Kiểm tra phương án dự phòng và hỏi người có kinh nghiệm trước khi cam kết.","lựa chọn","Giúp người hỏi nhận diện chi phí của đường tắt và lợi ích của lộ trình an toàn."],
  ["Ngọn đèn bàn học","THUẬN","Đêm yên, trang giấy còn thơm mực\nMột nét sửa đi sáng ý dần\nTri thức không về trong chớp mắt\nMỗi ngày góp chữ hóa thành văn","Học tập tiến triển nhờ nỗ lực đều đặn, sửa sai và tích lũy kiến thức có hệ thống.","Trang giấy sửa nét","Sai sót được nhận ra là một phần của quá trình hiểu sâu.","Đừng tự ép mình phải giỏi ngay hoặc so sánh tiến độ.","Chia mục tiêu học thành buổi ngắn, có ôn tập và phản hồi.","học tập","Liên hệ kết quả với phương pháp học cụ thể thay vì may rủi."],
  ["Hai ghế dưới hiên","BÌNH","Mưa rơi, hai ghế cùng im lặng\nMột chén trà nguội giữa đôi tay\nLời thật không cần chen tiếng lớn\nNghe hết lòng nhau, ấm lại ngày","Quan hệ có thể dịu đi khi hai bên dành chỗ cho lắng nghe chân thành.","Hai chiếc ghế","Sự hiện diện bình đẳng tạo không gian để đối thoại.","Lắng nghe không có nghĩa chấp nhận hành vi gây tổn thương.","Hẹn một cuộc trò chuyện bình tĩnh, nói rõ nhu cầu và ranh giới.","tình cảm","Tập trung vào khả năng đối thoại, không dự báo hòa giải chắc chắn."],
  ["Mái nhà đón gió","THUẬN","Mái tranh qua gió còn che bếp\nBàn tay chung vá lại đường xiên\nNhà ấm không nhờ tường thật kín\nMà nhờ người biết giữ bình yên","Gia đình vững hơn khi trách nhiệm được chia sẻ và mỗi người cùng chăm sóc không khí trong nhà.","Mái nhà được vá","Sự bền bỉ đến từ công sức chung, không phải vẻ ngoài hoàn hảo.","Đừng để một người gánh hết việc chăm sóc và hòa giải.","Cùng thống nhất một việc nhà hoặc trách nhiệm cần phân chia lại.","gia đình","Đưa lời khuyên về trách nhiệm cụ thể và sự công bằng giữa các thành viên."],
  ["Chiếc ví khâu chỉ","CẨN TRỌNG","Đồng tiền nhỏ khâu đường chỉ mảnh\nRơi một lần, khó nhặt đủ tay\nSổ sách mở ra soi khoản thiếu\nGiữ phần cần thiết trước ngày mai","Tài chính cần được nhìn bằng số liệu thật; kiểm soát khoản nhỏ giúp tránh thiếu hụt bất ngờ.","Đường chỉ trong ví","Ranh giới chi tiêu giữ nguồn lực khỏi rò rỉ từng chút.","Không vay hoặc đầu tư chỉ vì lời hứa lợi nhuận nhanh.","Ghi thu chi một tháng và xác định khoản dự phòng tối thiểu.","tài chính","Khuyến khích quyết định dựa trên ngân sách, không xem quẻ là tư vấn đầu tư."],
  ["Bậc đá sau mưa","THUẬN","Bậc rêu trơn, chân người còn vững\nTay vịn đưa qua dốc ngắn thôi\nVết ngã hôm qua thành lời nhắc\nBiết nhìn bàn chân, bước xa rồi","Khó khăn cũ có thể trở thành kinh nghiệm thực tế nếu người hỏi rút ra điều chỉnh phù hợp.","Tay vịn trên bậc đá","Hỗ trợ đáng tin giúp vượt đoạn khó mà không xóa đi nỗ lực cá nhân.","Đừng cố chứng minh mình mạnh bằng cách từ chối trợ giúp.","Nhờ một người đáng tin hỗ trợ đúng phần đang vướng.","nghị lực","Gợi khả năng phục hồi cùng sự trợ giúp, không tô hồng nỗi đau."],
  ["Cây cầu gỗ nhỏ","BÌNH","Bờ bên kia chưa thành gần gũi\nCây cầu còn thiếu một nhịp ngang\nNgười qua trước hãy dò từng ván\nTin nhau cần thử bước đàng hoàng","Quan hệ hợp tác cần được xây bằng những cam kết nhỏ có thể kiểm chứng.","Tấm ván cầu","Niềm tin hình thành qua trải nghiệm lặp lại, không chỉ qua lời nói.","Không trao quyền hoặc dữ liệu quan trọng khi chưa rõ trách nhiệm.","Thử hợp tác ở phạm vi nhỏ, ghi rõ vai trò và thời hạn.","quan hệ xã hội","Nhấn vào kiểm chứng và sự tương hỗ trong hợp tác."],
  ["Cửa sổ mở nửa","THUẬN","Cửa khép lâu nay vừa hé sáng\nGió mới chạm rèm, bụi cũng bay\nCơ hội thường đi cùng xáo trộn\nChọn điều cần giữ, mở bàn tay","Một thay đổi mới có triển vọng nhưng đòi hỏi người hỏi phân biệt điều nên giữ với điều nên đổi.","Cánh cửa hé","Cơ hội mở ra cùng những xáo động ban đầu.","Đừng nhận mọi thay đổi chỉ vì nó mới mẻ.","Nêu rõ điều kiện chấp nhận và điều không thể đánh đổi.","thay đổi","Cân bằng sự cởi mở với tiêu chí và ranh giới cá nhân."],
  ["Hạt muối trong chum","CẨN TRỌNG","Chum muối đầy, miệng chum chưa đậy\nMột mùa ẩm tới hóa vơi nhanh\nCủa dành cần nắp che mưa gió\nBiết giữ hôm nay, vững tháng quanh","Nguồn lực hiện có cần được bảo vệ trước rủi ro có thể dự liệu.","Chum muối không nắp","Tài sản tích lũy vẫn dễ hao hụt nếu thiếu biện pháp bảo vệ.","Đừng chủ quan vì hiện tại đang dư dả.","Rà lại bảo hiểm, khoản dự phòng và các nghĩa vụ sắp đến.","tài chính","Định hướng phòng ngừa rủi ro cụ thể, tránh dự đoán biến cố."],
  ["Mặt gương lau bụi","THUẬN","Gương mờ không làm trời thôi sáng\nKhăn mềm lau nhẹ, nét quen về\nNhìn lỗi của mình không tự trách\nSửa một điều thôi, lòng nhẹ ghê","Tự nhìn lại với lòng tử tế giúp người hỏi thay đổi điều có thể kiểm soát.","Mặt gương sáng dần","Nhận thức rõ hơn xuất hiện qua quan sát kiên nhẫn.","Đừng biến tự kiểm điểm thành tự kết án.","Viết một điều muốn sửa và một điểm mạnh sẽ dùng để sửa nó.","trưởng thành","Khuyến khích tự phản tỉnh có giới hạn và lòng tự trọng."],
  ["Bát cơm chia đôi","BÌNH","Bát cơm thơm đặt giữa hai người\nPhần ít vẫn ngon nếu thật lòng\nCho đi vừa sức, đừng quên mình\nLòng cho đi vẫn chừa phần mình","Sự sẻ chia có ý nghĩa khi đi cùng giới hạn lành mạnh và sự tôn trọng lẫn nhau.","Bát cơm chung","Chăm sóc là sự trao nhận cân bằng, không phải hy sinh một chiều.","Đừng dùng cho đi để mua sự công nhận.","Xác định phần mình có thể giúp mà không ảnh hưởng nhu cầu thiết yếu.","trách nhiệm","Phân biệt lòng tốt bền vững với việc tự làm kiệt sức."],
  ["Con thuyền đổi bến","CẨN TRỌNG","Bến cũ thân quen còn bóng cọc\nSông mới chưa đo độ nước sâu\nRời đi cần mang theo la bàn\nĐừng vì chán chỗ mà quên đường","Đổi hướng cần kế hoạch và hiểu rõ điều đang chờ phía trước.","La bàn trong thuyền","Mục tiêu và dữ liệu giúp phân biệt thay đổi có chủ đích với phản ứng nhất thời.","Đừng quyết định lớn chỉ để thoát cảm giác khó chịu nhất thời.","So sánh lựa chọn theo thu nhập, hỗ trợ, rủi ro và thời hạn thử.","công việc","Đề nghị đánh giá lựa chọn bằng tiêu chí có thể kiểm tra."],
  ["Tiếng chuông cuối lớp","THUẬN","Chuông tan, bài còn trang chưa hết\nBạn ngồi thêm nghe gió qua sân\nNgười học sâu không vì điểm số\nMà vì câu hỏi sáng trong dần","Tri thức phát triển khi sự tò mò được nuôi dưỡng vượt khỏi mục tiêu điểm số trước mắt.","Trang vở còn mở","Câu hỏi chưa giải đáp mở đường cho việc học tiếp.","Đừng để thành tích ngắn hạn quyết định giá trị bản thân.","Tìm một nguồn tin cậy để đào sâu câu hỏi còn bỏ ngỏ.","học tập","Khích lệ tò mò có kiểm chứng, không hứa thành tích."],
  ["Chiếc ô còn khô","BÌNH","Trời chưa mưa, ô nằm bên cửa\nMang theo không nặng một niềm lo\nChuẩn bị vừa tầm không gọi sợ\nBiết phòng khi cần, bước tự do","Chuẩn bị hợp lý giúp giảm lo âu và giữ quyền lựa chọn khi hoàn cảnh đổi khác.","Chiếc ô gấp","Dự phòng là sự sẵn sàng chứ không phải dự báo tai họa.","Đừng để chuẩn bị biến thành tích trữ quá mức.","Chuẩn bị một phương án dự phòng vừa sức cho việc quan trọng nhất.","cân bằng","Phân biệt chuẩn bị thực tế với lo lắng kéo dài."],
  ["Vườn sau mùa gặt","THUẬN","Rơm vàng nằm lại bên bờ ruộng\nĐất nghỉ một mùa vẫn giữ màu\nThành quả xong rồi cần hồi sức\nĐừng gieo liên tiếp đến khô sâu","Sau một giai đoạn nỗ lực, nghỉ ngơi và phục hồi là phần cần thiết của tiến trình lâu dài.","Đất nghỉ sau vụ gặt","Sự hồi phục giúp nguồn lực duy trì khả năng sinh trưởng.","Đừng xem nghỉ ngơi là lười biếng hoặc thất bại.","Đặt khoảng nghỉ thực sự sau mốc công việc lớn.","sức khỏe tinh thần","Tôn trọng giới hạn và khuyên tìm hỗ trợ chuyên môn nếu kiệt sức kéo dài."],
  ["Lời xin lỗi muộn","BÌNH","Lời xin lỗi đến sau mùa gió\nKhông xóa cành gãy khỏi sân nhà\nNhưng có thể dọn đường cho bước\nNếu người gây lỗi sửa từ nay","Lời xin lỗi chỉ có giá trị khi đi cùng trách nhiệm và hành động thay đổi.","Cành gãy được dọn","Khắc phục hậu quả có thể bắt đầu dù không đảo ngược quá khứ.","Không ép người bị tổn thương phải tha thứ ngay.","Nói rõ việc mình chịu trách nhiệm và cách sẽ bù đắp cụ thể.","quan hệ","Phân biệt lời xin lỗi, sửa sai và quyền lựa chọn của người nhận."],
  ["Hạt mưa trên mái tôn","CẨN TRỌNG","Mưa gõ dồn dập trên mái mỏng\nTiếng động làm lòng tưởng bão to\nHãy bước ra hiên nhìn mây thật\nĐừng để lời đồn hóa sóng to","Tin đồn và cảm giác có thể phóng đại nguy cơ; cần kiểm chứng trước khi phản ứng.","Mái hiên nhìn trời","Khoảng lùi giúp phân biệt tín hiệu thật với tiếng vang của lo lắng.","Không lan truyền điều chưa xác thực về người khác.","Kiểm tra nguồn độc lập và hỏi trực tiếp người liên quan khi phù hợp.","quan hệ xã hội","Nhắc kiểm chứng thông tin, tránh củng cố nghi kỵ."],
  ["Cây tre trước gió","THUẬN","Thân tre nghiêng theo chiều gió lộng\nGốc bền giữ đất khỏi rời xa\nMềm không có nghĩa là khuất phục\nBiết đổi dáng mình vẫn đứng qua","Linh hoạt trong cách làm có thể bảo vệ mục tiêu và giá trị cốt lõi.","Thân tre nghiêng","Sự thích nghi giúp chống chọi mà không mất gốc.","Đừng nhân danh linh hoạt để chấp nhận điều trái nguyên tắc.","Viết rõ điều có thể thương lượng và điều cần giữ vững.","nghị lực","Làm rõ ranh giới giữa thích nghi và tự đánh mất mình."],
  ["Thư chưa gửi","BÌNH","Trang thư nằm yên bên ngọn đèn\nMực khô chưa chắc lòng đã nguôi\nViết hết điều đau rồi đọc lại\nCó khi buông nhẹ chẳng cần gửi","Viết ra cảm xúc có thể giúp người hỏi hiểu mình trước khi chọn cách đối thoại.","Lá thư chưa gửi","Khoảng cách giữa cảm xúc và hành động cho phép lựa chọn sáng suốt.","Đừng gửi lời khi đang muốn làm đau người khác.","Viết nháp, nghỉ một đêm rồi quyết định có cần trao đổi hay không.","tình cảm","Khuyến khích điều hòa cảm xúc mà không áp đặt im lặng."],
  ["Bản đồ nét chì","THUẬN","Nét chì còn sửa trên trang giấy\nĐường vẽ hôm nay chưa phải rào\nMục tiêu rõ mà đường đi đổi\nNgười cầm bút, chọn đường mình đi","Kế hoạch có thể được điều chỉnh mà vẫn giữ mục tiêu do chính người hỏi lựa chọn.","Bản đồ chì","Lộ trình là công cụ có thể sửa, không phải số phận cố định.","Đừng thay mục tiêu liên tục chỉ vì một trở ngại nhỏ.","Chia mục tiêu thành chặng và xem lại kế hoạch theo dữ kiện mới.","định hướng","Giữ quyền chủ động của người hỏi, tránh ngôn ngữ định mệnh."],
  ["Giếng làng trong","THUẬN","Giếng trong soi mây giữa buổi trưa\nGầu kéo chậm, nước trong vẫn đầy\nĐiều tốt thường nằm trong nguồn sẵn\nBiết dùng vừa đủ, sạch tháng ngày","Nguồn lực tốt có thể đã ở gần; sử dụng có trách nhiệm giúp duy trì lâu dài.","Gầu nước trong","Giá trị sẵn có cần được tiếp cận và gìn giữ.","Không khai thác nguồn lực đến mức ảnh hưởng người khác.","Rà lại kỹ năng, mối quan hệ và công cụ đang có trước khi mua thêm.","cơ hội","Chuyển trọng tâm từ tìm kiếm vô hạn sang sử dụng tốt nguồn lực hiện có."],
  ["Vệt sáng qua khe cửa","BÌNH","Khe cửa hẹp mà tia nắng lọt\nKhông đủ soi hết cả căn phòng\nMột dữ kiện vừa tìm ra trước\nCòn nhiều câu hỏi đợi soi chung","Thông tin mới có ích nhưng chưa đủ để kết luận toàn bộ tình hình.","Tia sáng qua khe","Một manh mối mở hướng tìm hiểu, không thay thế bức tranh hoàn chỉnh.","Đừng kết luận từ một bằng chứng đơn lẻ.","Tìm thêm nguồn độc lập và ghi rõ điều gì vẫn chưa biết.","tri thức","Đánh giá mức độ chắc chắn và phần còn thiếu của bằng chứng."],
  ["Mùa hoa chậm nở","BÌNH","Nụ hoa giữ kín màu trong lá\nNắng đến nhiều phen mới hé cười\nĐiều đẹp có nhịp riêng của nó\nĐừng giục cành non phải nở tươi","Một tiến trình cần thời gian; người hỏi nên phân biệt kiên nhẫn với dấu hiệu trì trệ cần xử lý.","Nụ hoa khép","Phát triển có nhịp độ riêng và cần điều kiện thích hợp.","Chờ đợi cần đi cùng quan sát tiến triển thực tế.","Đặt vài dấu mốc nhỏ để biết quá trình có đang tiến lên.","thời điểm","Định nghĩa kiên nhẫn bằng dấu hiệu quan sát được."],
  ["Bậc cửa hai thế hệ","THUẬN","Ông kể chuyện cũ bên thềm gạch\nCháu hỏi ngày mai ở phía nào\nHai thời xa nhau cùng một mái\nTôn trọng khác nhau, nhà rộng cao","Gia đình nhiều thế hệ có thể gắn bó khi kinh nghiệm và lựa chọn mới được đối thoại bình đẳng.","Bậc cửa cũ","Không gian chung nối ký ức với điều đang hình thành.","Đừng dùng tuổi tác để phủ nhận quyền tự quyết của nhau.","Hỏi người thân điều họ lo và nói rõ điều mình cần tự quyết.","gia đình","Gợi đối thoại tôn trọng, không mặc định hòa thuận."],
  ["Con đường lát lại","THUẬN","Đá cũ nhấc lên bên đường xóm\nTừng viên đặt lại thẳng hàng hơn\nSửa lỗi chung cần nhiều bàn tay\nĐi chậm vài hôm, tiện lâu hơn","Cải thiện quy trình có thể bất tiện lúc đầu nhưng tạo nền tảng bền hơn nếu mọi người cùng góp sức.","Viên đá lát lại","Sửa cấu trúc từ gốc giúp giảm lặp lại cùng một trở ngại.","Đừng đổ hết trách nhiệm cho một người.","Xác định nguyên nhân gốc và thống nhất ai làm từng phần.","công việc","Hướng về giải quyết nguyên nhân, không chỉ chữa triệu chứng."],
  ["Chén nước tràn","CẨN TRỌNG","Chén đầy thêm giọt là tràn mép\nLòng người cũng có giới hạn thôi\nViệc nhỏ dồn lâu thành nặng gánh\nNói sớm còn hơn đợi vỡ rồi","Áp lực tích tụ cần được nhận diện và chia nhỏ trước khi ảnh hưởng sức khỏe hay quan hệ.","Giọt nước bên miệng chén","Giới hạn bị vượt qua bởi nhiều việc nhỏ nối tiếp.","Đừng chờ đến kiệt sức mới tìm trợ giúp.","Tạm dừng một cam kết ít cần thiết và trao đổi giới hạn của mình.","cân bằng","Không chẩn đoán; khuyến khích hỗ trợ khi khó khăn kéo dài."],
  ["Người thợ giữ khuôn","THUẬN","Bàn tay giữ khuôn cho đất đứng\nLửa nung vừa đủ, chén thành hình\nKỷ luật nâng điều mình mong muốn\nTự do cần khung để vững bền","Thói quen và cấu trúc phù hợp giúp biến mong muốn thành kết quả ổn định.","Khuôn gốm","Giới hạn hữu ích cho hình hài của ý tưởng.","Đừng biến kỷ luật thành trừng phạt bản thân.","Chọn một lịch làm việc có khoảng nghỉ và giữ thử hai tuần.","trách nhiệm","Đề xuất cấu trúc linh hoạt, không chủ trương kiểm soát cứng nhắc."],
  ["Lá thư hồi âm","BÌNH","Thư đi qua mấy mùa mưa nắng\nHồi âm không đến đúng ngày chờ\nKhoảng lặng đôi khi là bận rộn\nHỏi bằng lời thật, chớ đoán mơ","Sự chậm trễ trong giao tiếp cần được làm rõ thay vì tự dựng nên kết luận.","Phong thư chưa mở","Thiếu phản hồi là dữ kiện chưa đầy đủ, không tự nói lên nguyên nhân.","Đừng liên tục nhắn dồn hoặc suy diễn ý định.","Gửi một lời hỏi ngắn, tôn trọng thời gian và lựa chọn của họ.","giao tiếp","Khuyến khích hỏi trực tiếp và tôn trọng phản hồi."],
  ["Vườn chung nhiều luống","THUẬN","Mỗi luống gieo một loại rau riêng\nNước tưới chia đều cuối buổi chiều\nKhông ai cần trồng cùng một giống\nVườn tươi nhờ sắc lá đan xen","Tập thể vững mạnh khi khác biệt được phối hợp quanh mục tiêu và nguồn lực chung.","Nhiều luống rau","Đa dạng có thể bổ trợ thay vì cạnh tranh nếu chia sẻ công bằng.","Đừng ép mọi người thể hiện năng lực theo cùng một cách.","Phân vai theo thế mạnh và thống nhất cách chia nguồn lực.","quan hệ xã hội","Đưa ra giải pháp hợp tác cụ thể, coi trọng công bằng."],
  ["Ngọn đồi phủ sương","CẨN TRỌNG","Sương dày che mất hàng cây cuối\nĐừng bước nhanh khi mắt chưa quen\nĐứng lại nghe tiếng suối bên dốc\nRõ thêm phương hướng mới đi lên","Khi thông tin chưa đủ, tạm hoãn cam kết khó đảo ngược là lựa chọn khôn ngoan.","Sương phủ lối đồi","Tầm nhìn hạn chế cần được thừa nhận trước khi quyết định.","Không nhầm sự mơ hồ với dấu hiệu xấu chắc chắn.","Thu thập dữ kiện còn thiếu và đặt hạn cuối để xem lại.","lựa chọn","Hạn chế kết luận khi dữ kiện chưa rõ, đồng thời tránh chờ vô hạn."],
  ["Bàn tay gieo hạt","THUẬN","Bàn tay gieo hạt không đòi quả\nChỉ chọn đất lành, tưới đúng hôm\nViệc tốt hôm nay chưa thành tiếng\nMai này bóng mát phủ đường thôn","Nỗ lực có ý nghĩa dài hạn dù kết quả chưa xuất hiện ngay.","Hạt gieo bên đường","Hành động nhỏ có thể tạo lợi ích vượt quá thời điểm hiện tại.","Không phải mọi việc tốt đều đem lại kết quả như mong đợi.","Chọn một hành động tử tế có thể duy trì mà không cần được khen.","trách nhiệm","Nhấn giá trị của hành động đúng, không hứa quả báo."],
  ["Đèn đỏ giữa phố","CẨN TRỌNG","Đèn đỏ giữ dòng xe đang gấp\nMột nhịp dừng thôi tránh va chạm\nKhông phải cơ hội nào cũng mất\nBiết dừng đúng lúc giữ đường an","Một khoảng dừng ngắn có thể bảo vệ người hỏi khỏi quyết định vội và hậu quả không cần thiết.","Đèn đỏ giao lộ","Quy tắc dừng tạo an toàn cho nhiều người cùng lúc.","Đừng vin vào quy tắc để bỏ qua hoàn cảnh khẩn cấp thực sự.","Trước khi ký hoặc trả lời, đọc lại điều khoản và hậu quả.","công việc","Khuyên tạm dừng có chủ đích trước cam kết quan trọng."],
  ["Chiếc cầu sau lũ","BÌNH","Nước rút để lộ chân cầu yếu\nMuốn qua sông phải sửa từ nền\nKhó khăn không chỉ là cơn lũ\nMà là chỗ yếu bị bỏ quên","Sau biến cố, phục hồi bền vững cần xử lý điểm yếu đã lộ ra thay vì chỉ trở lại nhịp cũ.","Chân cầu sau lũ","Khủng hoảng cho thấy phần nền tảng cần được gia cố.","Đừng vội trở lại cường độ cũ khi chưa phục hồi.","Rà lại điều gì khiến vấn đề xảy ra và thay một quy trình cụ thể.","phục hồi","Hướng đến học hỏi và phục hồi thực tế, không trách người gặp nạn."],
  ["Giọt dầu cuối đèn","CẨN TRỌNG","Đèn còn sáng nhờ dầu ít ỏi\nThức thêm một đêm chẳng hóa khôn\nSức lực tiêu hoài không báo trước\nBiết châm thêm dầu, giữ trí bền","Năng lượng cá nhân cần được quản lý như một nguồn lực có giới hạn.","Ngọn đèn cạn dầu","Ánh sáng hiện tại không chứng minh nguồn lực còn vô tận.","Đừng coi kiệt sức là bằng chứng của tận tâm.","Giảm một đầu việc và dành thời gian ngủ, ăn, vận động phù hợp.","sức khỏe tinh thần","Khuyến khích chăm sóc cơ bản và tìm chuyên gia khi triệu chứng kéo dài."],
  ["Mảnh đất sau hàng rào","BÌNH","Sau hàng rào đất còn bỏ trống\nMuốn trồng cây cần hỏi chủ nhà\nCơ hội không phải quyền sở hữu\nTôn trọng ranh rồi mới gieo mầm","Một cơ hội chỉ nên theo đuổi khi quyền, sự đồng thuận và trách nhiệm đã rõ.","Mảnh đất có ranh","Tiềm năng không xóa bỏ quyền và giới hạn của người khác.","Không tự ý sử dụng tài sản, ý tưởng hay thời gian của người khác.","Xác nhận quyền sở hữu và điều kiện hợp tác bằng văn bản.","đạo đức","Làm rõ sự đồng thuận và quyền lợi của các bên."],
  ["Vệt phấn trên bảng","THUẬN","Bảng đen còn dòng sai cần xóa\nPhấn trắng viết lại chẳng ngại ngần\nLần làm trật không thành bản án\nSửa ngay từ đó, học thêm dần","Sai lầm có thể được sửa bằng nhận trách nhiệm và thay đổi cách làm.","Dòng phấn được xóa","Lỗi được nhận diện có thể trở thành bài học thay vì nhãn dán con người.","Đừng lặp lại lỗi rồi chỉ dựa vào lời hứa.","Nêu hậu quả, sửa phần còn sửa được và ghi cách phòng tránh.","trưởng thành","Cân bằng lòng tự tha thứ với trách nhiệm sửa sai."],
  ["Ngã ba ba biển chỉ","BÌNH","Ba tấm biển cùng ghi tên đường\nMỗi hướng đưa tới một miền riêng\nĐường đúng không nằm trong lời bói\nMà trong điều mình muốn giữ gìn","Lựa chọn phù hợp phụ thuộc vào giá trị, điều kiện và cái giá người hỏi sẵn lòng chấp nhận.","Ngã ba đường","Không có lựa chọn phù hợp cho mọi người; tiêu chí cá nhân rất quan trọng.","Đừng giao quyền quyết định của mình cho quẻ hay người khác.","Viết ba tiêu chí ưu tiên rồi chấm từng phương án theo dữ kiện.","lựa chọn","Khẳng định quyền tự quyết và phương pháp so sánh."],
  ["Rổ cá vừa đủ","THUẬN","Người chài về bến, rổ vừa đầy\nKhông kéo thêm cá quá sức thuyền\nBiết điểm dừng cũng là khôn ngoan\nGiữ phần mai tới, nước còn yên","Biết giới hạn và thời điểm dừng giúp bảo toàn thành quả và khả năng tiếp tục.","Rổ cá vừa đầy","Đủ dùng đôi khi có giá trị hơn tích lũy thêm bằng mọi giá.","Đừng lấy quẻ làm lý do bỏ qua nghĩa vụ đã nhận.","Xác định tiêu chí hoàn thành trước khi tiếp tục mở rộng.","cân bằng","Kết nối sự đủ đầy với trách nhiệm và tính bền vững."],
  ["Người bạn giữ lời","THUẬN","Hẹn chiều, người đến không cần nhắc\nMột việc nhỏ thôi giữ chữ tin\nDanh tiếng xây từ bao lần đúng\nĐừng nói quá xa sức của mình","Uy tín được hình thành qua những cam kết nhỏ được thực hiện nhất quán.","Cuộc hẹn đúng giờ","Sự đáng tin cậy hiện rõ qua hành động lặp lại.","Đừng nhận thêm việc chỉ để làm vừa lòng người khác.","Rà soát lịch và chỉ hứa điều có thể hoàn thành.","quan hệ xã hội","Khuyến khích sự chân thật thay vì lời hứa lớn."],
  ["Thửa ruộng nhiễm mặn","CẨN TRỌNG","Lúa non vàng lá giữa đồng mặn\nTưới thêm bao lần chẳng hóa xanh\nĐổi nguồn nước trước khi gieo lại\nNỗ lực sai nơi hóa mong manh","Khi cố gắng không cải thiện tình hình, cần xem lại điều kiện và phương pháp thay vì chỉ tăng cường độ.","Đất ruộng nhiễm mặn","Môi trường không phù hợp có thể vô hiệu hóa nỗ lực cá nhân.","Đừng quy mọi thất bại cho thiếu cố gắng.","Tìm nguyên nhân bên ngoài và hỏi ý kiến chuyên môn trước khi đầu tư thêm.","công việc","Giúp nhận diện điều kiện hệ thống và tránh tự trách đơn giản."],
  ["Hạt bụi trong nắng","BÌNH","Nắng xiên làm bụi bay thành vệt\nMắt thấy nhiều hơn lúc trời trong\nMột chuyện nhỏ qua lời thêm bớt\nBình tâm hỏi lại mới tỏ lòng","Góc nhìn và lời kể có thể làm thay đổi cảm nhận về một sự việc.","Bụi bay trong nắng","Điều nổi bật trước mắt không luôn là điều quan trọng nhất.","Không bác bỏ cảm xúc, nhưng cũng đừng lấy cảm xúc làm toàn bộ bằng chứng.","Tách điều mình thấy, điều mình nghe và điều mình suy đoán.","giao tiếp","Phân biệt quan sát với diễn giải, lắng nghe nhiều phía."],
  ["Mùa đông giữ củ","THUẬN","Củ nằm yên dưới tầng đất lạnh\nKhông phô màu mà vẫn nuôi cây\nCó lúc lùi sâu để giữ sức\nĐến mùa phù hợp sẽ vươn đầy","Giai đoạn ít biểu hiện không đồng nghĩa mất tiến triển; duy trì nền tảng có thể là ưu tiên.","Củ dưới đất lạnh","Sự phát triển đôi khi diễn ra âm thầm và kín đáo.","Đừng dùng hình ảnh này để biện minh cho tình trạng trì trệ kéo dài.","Theo dõi một chỉ dấu tiến bộ nhỏ theo tuần.","kiên nhẫn","Cân bằng nghỉ dưỡng với việc kiểm tra tiến triển thực."],
  ["Tờ hóa đơn gấp","CẨN TRỌNG","Tờ giấy gấp giấu dòng tiền lẻ\nMở ra mới rõ món nào thừa\nKhông nhìn con số không làm mất\nChỉ khiến khoản nợ lớn thêm dần","Đối diện sớm với nghĩa vụ tài chính giúp người hỏi có thêm lựa chọn xử lý.","Hóa đơn được mở","Sự minh bạch làm vấn đề cụ thể và có thể giải quyết.","Đừng vay khoản mới để che khoản cũ khi chưa có kế hoạch.","Liệt kê nợ, lãi, hạn trả và liên hệ bên cho vay để hỏi phương án.","tài chính","Không tư vấn pháp lý/tài chính cá nhân; khuyên tìm chuyên gia đáng tin."],
  ["Cành hoa cắm nước","BÌNH","Hoa rời cành vẫn còn hương nhẹ\nBình nước chăm từng buổi sớm mai\nĐiều đã đổi không còn như cũ\nVẫn có cách sống đẹp hôm nay","Mất mát có thể đổi hình thức sống nhưng không xóa hết giá trị và khả năng tiếp tục.","Cành hoa trong bình","Chăm sóc hiện tại tạo chỗ cho vẻ đẹp sau biến đổi.","Đừng ép mình phải vui hoặc hồi phục theo hạn định của ai.","Giữ một nếp sinh hoạt nhỏ và tìm người hỗ trợ khi cần.","mất mát","Thừa nhận đau buồn, không hứa thời gian hồi phục."],
  ["Cây cầu có lan can","THUẬN","Cầu cao mở lối qua sông rộng\nLan can giữ bước khỏi chênh vênh\nMục tiêu lớn cần khung an toàn\nCó kế hoạch rồi hãy tiến nhanh","Tham vọng có thể theo đuổi vững vàng hơn khi đi kèm tiêu chuẩn an toàn và kế hoạch.","Lan can cây cầu","Biện pháp bảo vệ giúp hành trình táo bạo trở nên bền hơn.","Đừng nhầm tự tin với miễn nhiễm rủi ro.","Đặt ngưỡng dừng lỗ, ngân sách hoặc điều kiện an toàn phù hợp.","cơ hội","Khuyến khích tiến lên có giới hạn bảo vệ."],
  ["Dòng sông đổi màu","CẨN TRỌNG","Nước đầu nguồn nay đục hơn rồi\nĐừng vội uống khi chưa lọc trong\nTin mới đến cần xem nguồn gốc\nGiữ mình tỉnh táo trước đám đông","Thông tin hoặc lời mời mới cần được kiểm chứng nguồn gốc trước khi tin hay hành động.","Dòng nước đục","Tín hiệu bất thường đòi hỏi bước kiểm tra.","Không chia sẻ thông tin cá nhân hoặc tiền khi chưa xác thực danh tính.","Gọi qua kênh độc lập và xác nhận điều khoản trước khi chuyển tiền.","an toàn","Nêu biện pháp xác thực, không khơi sợ hãi."],
  ["Đôi giày vừa chân","THUẬN","Giày vừa chân đi đường xa được\nKhông cần sáng bóng giữa phố đông\nCông việc hợp mình nuôi sức bền\nChọn nơi làm được điều có nghĩa","Công việc phù hợp với năng lực và giá trị có thể bền vững hơn vẻ hào nhoáng bên ngoài.","Đôi giày vừa chân","Sự phù hợp giúp duy trì bước đi dài.","Đừng bỏ qua lương, điều kiện và quyền lợi thiết yếu.","So sánh cơ hội theo môi trường, thu nhập, học hỏi và sức khỏe.","công việc","Không lý tưởng hóa đam mê; cân nhắc thực tế và quyền lợi."],
  ["Tiếng nói trong phòng họp","BÌNH","Ý kiến khác vang lên giữa phòng\nKhông làm bàn họp vỡ đôi đâu\nHỏi thêm lý lẽ, cùng soi xét\nKhác góc nhìn mở lối hiểu sâu","Bất đồng có thể cải thiện quyết định nếu các bên tập trung vào lý lẽ và mục tiêu chung.","Chiếc ghế đối diện","Góc nhìn khác mở rộng phần dữ kiện nhóm đang thiếu.","Không phải bất đồng nào cũng an toàn; giữ ranh giới khi bị xúc phạm.","Nhắc lại ý người kia rồi nêu dữ kiện mình đang có.","công việc","Gợi đối thoại có cấu trúc và nhận diện môi trường thiếu an toàn."],
  ["Bếp lửa mùa mưa","THUẬN","Mưa dài, bếp than còn đỏ lửa\nNồi canh chung ấm cả gian nhà\nChăm một điều nhỏ trong ngày tối\nHy vọng nảy từ điều gần ta","Khi hoàn cảnh nặng nề, chăm sóc những điều thiết thực gần mình có thể tạo điểm tựa.","Bếp than đỏ","Nguồn ấm nhỏ vẫn có ý nghĩa trong thời kỳ khó khăn.","Đừng xem lời khuyên này là thay thế hỗ trợ chuyên môn.","Chọn một nhu cầu thiết yếu hôm nay và nhờ người thân giúp nếu cần.","hy vọng","Nuôi hy vọng bằng hành động nhỏ, không phủ nhận hoàn cảnh khó."],
  ["Bản lề được tra dầu","THUẬN","Cửa cũ kêu lâu ngày mới mở\nMột giọt dầu làm nhẹ bản lề\nĐiều vướng đôi khi chỉ cần sửa\nĐừng thay cả nhà vì tiếng kêu","Một điều chỉnh nhỏ đúng chỗ có thể tháo gỡ trở ngại lớn hơn việc thay đổi toàn bộ.","Bản lề tra dầu","Bảo trì có mục tiêu giúp phục hồi hoạt động vốn có.","Nếu vấn đề có nguyên nhân sâu, đừng chỉ xử lý phần biểu hiện.","Thử một thay đổi nhỏ, đo kết quả rồi mới mở rộng.","giải quyết vấn đề","Đề xuất thử nghiệm nhỏ với tiêu chí đánh giá."],
  ["Mưa trên mái kính","BÌNH","Mưa chảy dài trên ô kính trong\nCảnh vật cong theo vệt nước trôi\nChờ khô rồi xem đường chân thật\nCảm xúc lắng, mắt sẽ sáng thôi","Cảm xúc mạnh có thể làm nhận định méo đi; người hỏi nên chờ ổn định rồi đánh giá lại.","Vệt nước trên kính","Cảm xúc tạo lớp lọc tạm thời lên điều ta quan sát.","Không trì hoãn việc cần xử lý khẩn cấp hoặc nguy hiểm.","Ghi nhận cảm xúc, đợi bình tâm rồi kiểm tra lại dữ kiện.","cân bằng","Hướng dẫn tự điều hòa và phân biệt tình huống khẩn cấp."],
  ["Gánh hàng qua dốc","CẨN TRỌNG","Gánh nặng chia đều qua hai đầu\nMột bên quá nặng, vai lệch nghiêng\nViệc chung cần cân phần đóng góp\nNói sớm kẻo mỏi cả hai bên","Trách nhiệm mất cân bằng cần được thương lượng trước khi gây kiệt sức hoặc bất mãn.","Đòn gánh lệch","Sự bất cân xứng kéo dài làm cả quan hệ lẫn công việc suy yếu.","Đừng im lặng mong người khác tự nhận ra.","Liệt kê phần việc và đề nghị phân chia lại bằng tiêu chí rõ.","trách nhiệm","Khuyến khích giao tiếp trực tiếp và đo khối lượng thực tế."],
  ["Người học nghề mới","THUẬN","Bàn tay vụng chạm vào mũi đục\nĐường khắc lệch rồi sửa từng hôm\nNgười giỏi cũng từng qua lúng túng\nCứ hỏi, cứ làm, tay vững dần","Bắt đầu ở vị trí người học là bước bình thường để hình thành năng lực mới.","Mũi đục mới cầm","Thành thạo đến từ luyện tập, hướng dẫn và sửa lỗi.","Đừng nhận việc vượt quá năng lực mà không có giám sát.","Tìm người hướng dẫn và xin phản hồi cụ thể sau mỗi lần thử.","học tập","Khuyến khích học nghề an toàn và phản hồi hữu ích."],
  ["Cánh cửa đóng nhẹ","BÌNH","Cánh cửa khép mà không tiếng động\nCó lần chia tay chẳng hơn thua\nĐôi khi rời đi là tôn trọng\nGiữ phẩm giá mình, đỡ tổn thương","Một kết thúc có thể được xử lý bằng sự rõ ràng và tôn trọng, dù cảm xúc còn phức tạp.","Cánh cửa khép êm","Kết thúc không nhất thiết cần tranh thắng thua.","Đừng ở lại nơi có bạo lực hoặc ép buộc chỉ để giữ hình thức.","Nói rõ điều kết thúc, bảo vệ an toàn và nhờ người tin cậy hỗ trợ.","tình cảm","Ưu tiên an toàn cá nhân; không mặc định phải hòa giải."],
  ["Hạt giống gửi kho","BÌNH","Hạt giống được cất nơi khô ráo\nChưa gieo không có nghĩa bỏ mùa\nĐợi đất đủ ẩm rồi xuống giống\nChuẩn bị kỹ để khỏi phí công","Một dự định có thể cần thời gian chuẩn bị trước khi thực hiện.","Hạt giống trong kho","Bảo quản kế hoạch giúp duy trì khả năng hành động đúng lúc.","Chuẩn bị không nên trở thành lý do trì hoãn mãi.","Xác định điều kiện bắt đầu và ngày đánh giá lại.","khởi đầu","Chuyển ý định chờ đợi thành ngưỡng bắt đầu cụ thể."],
  ["Lối mòn trong rừng","CẨN TRỌNG","Lối mòn cũ dẫn về nơi quen\nNhưng cầu gỗ trước đã mục rồi\nThói quen tốt cũng cần xem lại\nĐừng bước theo vì đã bước thôi","Cách làm từng hiệu quả có thể không còn phù hợp với hoàn cảnh hiện tại.","Cầu gỗ mục","Thành công quá khứ không tự đảm bảo an toàn hiện nay.","Đừng phủ nhận điều cũ chỉ vì muốn khác biệt.","Kiểm tra giả định cũ bằng dữ kiện hiện tại trước khi tiếp tục.","thay đổi","Đánh giá lại thói quen một cách công bằng, không cực đoan."],
  ["Bình trà bớt nóng","BÌNH","Trà mới rót còn đầy hơi nóng\nChờ một nhịp rồi mới nhấp môi\nLời vừa giận cũng như hơi nước\nLắng xuống rồi nói sẽ sáng lời","Trao đổi nhạy cảm thường hiệu quả hơn khi người hỏi có thời gian điều hòa cảm xúc.","Bình trà nóng","Một khoảng nghỉ giúp tránh làm tổn thương nhau bằng lời bốc đồng.","Không dùng im lặng kéo dài để trừng phạt người khác.","Xin hẹn nói lại sau một khoảng nghỉ cụ thể.","giao tiếp","Khuyến khích tạm dừng có thời hạn và quay lại đối thoại."],
  ["Đồng hồ chậm một nhịp","THUẬN","Kim đồng hồ trễ mất vài phút\nVẫn chỉ đường dài qua tháng năm\nTiến độ khác nhau không thành lỗi\nMiễn còn bước tới đúng phần mình","Mỗi người có tốc độ riêng; điều quan trọng là tiến triển thực và nhịp sống có thể duy trì.","Kim đồng hồ chậm","Khác biệt tốc độ không đồng nghĩa với kém cỏi.","Đừng lấy sự chậm rãi làm cớ bỏ qua hạn chót quan trọng.","Chọn mốc tiến bộ phù hợp và kiểm tra lịch cam kết thực tế.","trưởng thành","Cân bằng sự cảm thông với trách nhiệm về thời hạn."],
  ["Bờ kè còn khe nứt","CẨN TRỌNG","Bờ kè nhìn xa còn vững chãi\nKhe nứt nhỏ ăn sâu dưới chân\nSớm gọi người xem kỹ nền móng\nĐừng chờ nước lớn mới phân vân","Dấu hiệu nhỏ của rủi ro nên được kiểm tra sớm trước khi hậu quả khó kiểm soát.","Khe nứt bờ kè","Bề ngoài nguyên vẹn không thay thế việc kiểm tra cấu trúc.","Không tự sửa vấn đề kỹ thuật hoặc sức khỏe vượt quá chuyên môn.","Ghi lại dấu hiệu và tìm người có chuyên môn đánh giá.","an toàn","Khuyên kiểm tra chuyên môn, không tự chẩn đoán."],
  ["Tấm vé chưa ghi tên","BÌNH","Tấm vé còn trắng chưa vào cửa\nChỗ ngồi phía trong chưa ai trao\nMuốn đi xa cần hỏi điều kiện\nĐừng mua niềm tin bằng lời chào","Lời mời hấp dẫn cần được kiểm tra điều kiện và tính xác thực trước khi chấp nhận.","Tấm vé trắng","Cơ hội mới chỉ là lời hứa cho tới khi điều kiện được xác nhận.","Cảnh giác yêu cầu trả trước hoặc bảo mật bất thường.","Đọc thỏa thuận, xác minh đơn vị và lưu lại trao đổi.","cơ hội","Nêu cách xác minh cơ hội và nhận biết rủi ro."],
  ["Bông lúa cúi đầu","THUẬN","Bông lúa nặng hạt cúi đầu thấp\nNgười hiểu nhiều chẳng vội hơn thua\nKhiêm nhường không làm mình nhỏ lại\nMở đường cho học hỏi quanh ta","Năng lực vững thường đi cùng thái độ sẵn lòng học và chia sẻ công lao.","Bông lúa trĩu hạt","Thành quả có thể nuôi sự khiêm nhường thay vì phô trương.","Đừng hạ thấp bản thân để người khác thấy dễ chịu.","Ghi nhận đóng góp của mình và của người cùng làm.","trưởng thành","Phân biệt khiêm nhường với tự phủ nhận."],
  ["Cửa hàng vắng khách","CẨN TRỌNG","Sạp hàng im dưới chiều mưa bụi\nĐếm khách qua đường chẳng đủ dùng\nHỏi người mua cần gì trước đã\nĐổi món hàng rồi tính vốn chung","Khi kết quả kinh doanh yếu, cần lắng nghe nhu cầu và xem lại mô hình trước khi chi thêm.","Sạp hàng vắng","Tín hiệu thị trường cần được phân tích, không chỉ chờ vận may.","Đừng vay thêm vốn nếu chưa hiểu dòng tiền và rủi ro.","Nói chuyện với khách, rà biên lợi nhuận và lập giới hạn chi.","tài chính","Không đảm bảo lợi nhuận; khuyên dùng số liệu và cố vấn."],
  ["Mắt lưới chiếc vó","BÌNH","Mắt lưới đều giữ dòng cá nhỏ\nMột ô rách thôi lọt cả đàn\nQuy trình tốt cần xem chi tiết\nĐừng chỉ nhìn thành quả huy hoàng","Một hệ thống có thể thất thoát ở chi tiết nhỏ; kiểm tra quy trình giúp bảo vệ công sức.","Mắt lưới rách","Khoảng trống nhỏ trong quy trình có thể gây mất mát lặp lại.","Không theo dõi quá mức đến mức mất niềm tin với mọi người.","Kiểm tra một bước bàn giao hoặc đối soát thường bị bỏ qua.","công việc","Gợi cách cải tiến quy trình có trọng điểm."],
  ["Nước mát đầu nguồn","THUẬN","Dòng nước mát tìm đường qua đá\nKhông tranh phần, vẫn đến đồng xa\nLời nói mềm không là yếu đuối\nKiên trì đôi khi thắng tiếng la","Sự bền bỉ và cách giao tiếp điềm tĩnh có thể tạo ảnh hưởng lâu dài.","Dòng nước qua đá","Kiên trì thay đổi vật cản bằng tác động liên tục, không phải đối đầu ồn ào.","Đừng dùng nhẫn nhịn để ở trong tình huống nguy hiểm.","Chọn một thông điệp ngắn, rõ và lặp lại bình tĩnh.","quan hệ","Phân biệt mềm mỏng với cam chịu, ưu tiên an toàn."],
  ["Người giữ chìa khóa","CẨN TRỌNG","Chìa khóa trao tay cần đúng cửa\nTin cậy mà vẫn rõ phần trao\nQuyền hạn mở ra bao lối đi\nGhi ai chịu trách nhiệm về sau","Trao quyền hoặc thông tin cần đi cùng phạm vi rõ ràng và trách nhiệm giải trình.","Chìa khóa trong tay","Quyền tiếp cận phải tương xứng với trách nhiệm và sự tin cậy.","Không chia sẻ mật khẩu hoặc giấy tờ nhạy cảm tùy tiện.","Giới hạn quyền truy cập và lập danh sách người chịu trách nhiệm.","trách nhiệm","Đề xuất nguyên tắc bảo mật và trách nhiệm rõ."],
  ["Bàn tay nối việc","THUẬN","Người trước trao kìm, người sau đón\nCông việc liền mạch giữa xưởng đông\nBàn giao rõ ràng không mất sức\nĐội cùng hiểu việc, tiến mới thông","Hợp tác hiệu quả khi thông tin bàn giao và kỳ vọng được nói rõ.","Chiếc kìm được trao","Kết nối giữa người làm giảm gián đoạn và sai sót.","Đừng mặc định đồng nghiệp đã hiểu điều chưa nói.","Dùng danh sách bàn giao ngắn với người phụ trách và hạn hoàn thành.","công việc","Tập trung vào giao tiếp rõ và khả năng kiểm chứng."],
  ["Bức tường mới xây","BÌNH","Hàng gạch đầu tiên đặt thẳng ngay\nTường cao nhờ mỗi lớp ngay ngắn\nQuan hệ cũng cần nền tin cậy\nLời nhỏ giữ đều, vững tháng năm","Niềm tin trong quan hệ cần được xây qua hành động nhất quán và tôn trọng.","Hàng gạch đầu","Nền tảng ban đầu quyết định độ vững của điều xây tiếp.","Đừng đòi tin tưởng ngay khi chưa có thời gian kiểm chứng.","Thống nhất một cam kết nhỏ và xem cả hai có thực hiện không.","tình cảm","Không phán đoán lòng người; dựa vào hành vi quan sát được."],
  ["Ngọn đồi có đường xuống","CẨN TRỌNG","Lên cao dễ tưởng mình đã tới\nNhìn xuống mới biết dốc còn dài\nThành công cần đường lui an toàn\nGiữ chân trên đất, mắt nhìn xa","Khi đang thuận lợi, người hỏi vẫn cần quản trị rủi ro và chuẩn bị phương án dự phòng.","Đường xuống đồi","Thành quả vững cần lối thoát và sự khiêm tốn trước biến động.","Đừng mở rộng quá nhanh chỉ vì vài kết quả tốt.","Giữ quỹ dự phòng và xác định ngưỡng dừng trước quyết định lớn.","tài chính","Khuyến khích phòng ngừa ngay cả lúc thuận lợi."],
  ["Tiếng chim lúc rạng đông","THUẬN","Chim gọi bình minh trên mái ngói\nĐêm dài cũng đã nhường chân mây\nSau quãng tối, ngày không tự đến\nMở cửa ra sân, đón nắng này","Hy vọng có thể đi cùng một hành động nhỏ để bắt đầu lại sau thời kỳ khó khăn.","Tiếng chim rạng đông","Tín hiệu khởi sắc cần người hỏi đáp lại bằng bước đi thực tế.","Không ép mình phải hồi phục nhanh vì người khác mong đợi.","Chọn việc nhỏ nhất giúp ngày hôm nay dễ chịu và có trật tự hơn.","hy vọng","Lạc quan thực tế, chú ý hỗ trợ khi người hỏi đang khủng hoảng."],
  ["Nút thắt dây thừng","BÌNH","Dây rối càng giật càng thêm chặt\nNới đầu mối rồi gỡ từng vòng\nViệc khó cần nhìn nơi mắc trước\nChia nhỏ ra làm, lối sẽ thông","Vấn đề phức tạp dễ giải quyết hơn khi tìm nút thắt đầu tiên và xử lý từng phần.","Nút dây được nới","Thay đổi cách tiếp cận có thể tháo gỡ sự bế tắc.","Đừng đổ lỗi cho bản thân vì chưa giải được tất cả cùng lúc.","Viết vấn đề thành ba phần và bắt đầu ở phần mình kiểm soát.","giải quyết vấn đề","Ưu tiên bước nhỏ, cụ thể và có thể kiểm soát."],
  ["Mâm cơm thiếu một người","BÌNH","Mâm cơm đặt dư thêm đôi đũa\nChỗ trống vẫn còn ấm tiếng cười\nNhớ thương không cần che cho kín\nKể chuyện ngày xưa, rồi bước tiếp","Nỗi nhớ người vắng mặt có thể cùng tồn tại với việc tiếp tục chăm sóc cuộc sống hiện tại.","Đôi đũa đặt thêm","Nghi thức tưởng nhớ tạo không gian cho tình cảm và sự tiếp nối.","Đừng áp đặt cách để tang hay tưởng nhớ lên người khác.","Chia sẻ một kỷ niệm với người thân hoặc làm một việc tưởng niệm phù hợp.","mất mát","Tôn trọng khác biệt trong đau buồn; gợi kết nối hỗ trợ."],
  ["Hạt cát trong máy đồng hồ","CẨN TRỌNG","Hạt cát kẹt ngang vòng bánh nhỏ\nKim đứng im dù máy còn đầy\nTìm đúng chỗ vướng rồi làm sạch\nĐừng thay toàn bộ chỉ vì chậm","Trở ngại có thể nằm ở một điểm nhỏ; chẩn đoán trước khi thay đổi lớn sẽ tiết kiệm nguồn lực.","Bánh răng mắc cát","Một nguyên nhân cụ thể có thể gây đình trệ toàn hệ thống.","Không quy kết lỗi khi chưa kiểm tra nguyên nhân.","Thử nghiệm từng khâu và ghi lại thời điểm vấn đề bắt đầu.","công việc","Khuyên phân tích nguyên nhân thay vì phản ứng vội."],
  ["Lá non sau vết cắt","THUẬN","Cành cũ vừa tỉa còn vết nhựa\nChồi non mới lên cạnh khoảng trống\nBuông một phần không là mất hết\nCó chỗ cho điều khác vươn lên","Từ bỏ một điều không còn phù hợp có thể mở không gian cho hướng phát triển khác.","Chồi bên vết tỉa","Sự thay đổi tạo chỗ cho hình thức phát triển mới.","Đừng cắt bỏ điều quan trọng chỉ vì đang thất vọng nhất thời.","Liệt kê điều đang tiêu hao sức lực và cân nhắc một giới hạn mới.","thay đổi","Hỗ trợ quyết định buông bỏ có cân nhắc và không cực đoan."],
  ["Bước chân qua vạch","BÌNH","Vạch sơn phân đôi sân chơi nhỏ\nBước qua cần biết luật đôi bên\nRanh giới rõ làm trò chơi đẹp\nTôn trọng nhau thì dễ gần thêm","Ranh giới được thống nhất giúp quan hệ an toàn và công bằng hơn.","Vạch sân chơi","Quy ước rõ ràng bảo vệ sự tham gia của mọi bên.","Đừng lấy ranh giới làm cách trừng phạt hoặc kiểm soát người khác.","Nói rõ điều mình đồng ý và điều mình sẽ làm nếu ranh giới bị vượt.","quan hệ","Khuyến khích ranh giới tự bảo vệ, không thao túng."],
  ["Cơn gió đổi chiều","CẨN TRỌNG","Buồm căng khi gió còn thuận hướng\nMây kéo ngang trời, nước khác đi\nNhìn cờ báo gió trước khi kéo\nĐổi cách chèo giữ được thuyền yên","Điều kiện đang thay đổi; linh hoạt sớm có thể giảm thiệt hại và giữ mục tiêu quan trọng.","Lá cờ báo gió","Nhận biết tín hiệu sớm giúp điều chỉnh trước khi rủi ro tăng.","Đừng đổi hướng theo mọi biến động nhỏ.","Theo dõi hai chỉ số báo trước và đặt điều kiện điều chỉnh.","công việc","Khuyến nghị dựa trên chỉ báo cụ thể thay vì phản ứng theo tin đồn."],
  ["Người gác thư viện","THUẬN","Trang sách trao tay qua năm tháng\nNgười giữ kho không giữ riêng mình\nTri thức sáng hơn khi chia sẻ\nGhi nguồn rõ ràng, học chân tình","Chia sẻ kiến thức có trách nhiệm giúp cộng đồng cùng tiến bộ.","Cuốn sách mượn","Tri thức lưu chuyển tốt khi nguồn và công sức được ghi nhận.","Đừng dùng công sức người khác như thể của mình.","Chia sẻ điều hữu ích kèm nguồn và ghi nhận tác giả.","tri thức","Đề cao trung thực nguồn, không tự nhận quyền tác giả."],
  ["Bình gốm rạn men","BÌNH","Vết rạn chạy dọc đường men xưa\nChén vẫn dùng nếu biết nâng niu\nKhông phải nguyên vẹn mới có giá\nSống thật cùng nhau mới bền nhiều","Khuyết điểm không làm mất giá trị, nhưng cần được nhìn nhận và chăm sóc đúng cách.","Bình gốm rạn","Sự không hoàn hảo có thể cùng tồn tại với công năng và vẻ đẹp.","Đừng lãng mạn hóa tổn thương hay xem nhẹ sửa chữa cần thiết.","Thừa nhận điều chưa ổn và chọn cách chăm sóc phù hợp.","trưởng thành","Không biến khó khăn thành điều phải biết ơn; nhấn nhu cầu sửa chữa."],
  ["Dòng chữ trong sổ nợ","CẨN TRỌNG","Tên người ghi giữa trang giấy trắng\nNợ nghĩa tình cũng cần ranh riêng\nGiúp nhau đừng thành dây buộc chặt\nNói rõ từ đầu, nhẹ đôi bên","Sự giúp đỡ cần minh bạch để tránh biến thành áp lực hoặc ràng buộc không mong muốn.","Dòng ghi trong sổ","Ghi nhớ nghĩa vụ giúp bảo vệ lòng tin và sự tự nguyện.","Đừng cho vay số tiền mình không thể mất.","Thỏa thuận rõ khoản tiền, thời hạn và khả năng hoàn trả.","tài chính","Tránh cổ súy vay mượn cảm tính; đề cao minh bạch."],
  ["Chiếc ghế nhường chỗ","THUẬN","Ghế bên cửa nhường người mới đến\nMột chỗ nhỏ thôi đủ ấm lòng\nTập thể mạnh khi ai cũng thấy\nMình có phần trong tiếng nói chung","Sự bao gồm và nhường chỗ đúng lúc giúp mọi người cùng tham gia.","Chiếc ghế được nhường","Không gian và quyền lên tiếng có thể được chia sẻ công bằng.","Nhường chỗ không có nghĩa gánh thay trách nhiệm người khác.","Mời người ít được nghe phát biểu trước khi chốt quyết định.","quan hệ xã hội","Đưa hành động bao gồm cụ thể, tránh hình thức."],
  ["Bức thư từ chính mình","BÌNH","Mai này đọc lại dòng hôm nay\nĐừng viết lời mình chẳng tin đâu\nChọn điều làm được trong tầm với\nGiữ lời với mình, bắt đầu mau","Cam kết nhỏ với bản thân đáng tin hơn lời hứa lớn không có kế hoạch.","Bức thư gửi tương lai","Lời nhắn tạo cầu nối giữa ý định và hành động hiện tại.","Đừng tự phạt mình nếu hoàn cảnh buộc phải đổi kế hoạch.","Viết một cam kết đo được và cách điều chỉnh nếu có trở ngại.","trách nhiệm","Khuyến khích cam kết linh hoạt và tự cảm thông."],
  ["Bàn tay buông dây diều","THUẬN","Diều bay cao nhờ dây còn giữ\nBuông đúng lúc, gió đẩy xa hơn\nGiữ chặt quá làm khung tre gãy\nTin vừa đủ, mắt dõi theo đường","Trao quyền có kiểm soát giúp người khác trưởng thành mà vẫn giữ được kết nối.","Sợi dây diều","Kết nối lành mạnh cho phép tự do trong giới hạn an toàn.","Đừng giám sát đến mức xâm phạm quyền riêng tư.","Thống nhất mục tiêu và điểm cần báo lại, rồi giao phần việc phù hợp.","gia đình","Cân bằng tin cậy và an toàn, nhất là trong chăm sóc người thân."],
  ["Bến xe chuyến cuối","CẨN TRỌNG","Bảng giờ đổi khi chiều đã muộn\nĐường về còn cách mấy con dốc\nHỏi người trực bến trước khi đợi\nKẻo hết chuyến rồi mới lo toan","Kế hoạch phụ thuộc thời hạn cần được kiểm tra sớm để tránh bị động.","Bảng giờ xe","Thông tin cập nhật quan trọng hơn giả định dựa trên lịch cũ.","Đừng đặt cược vào một phương án duy nhất khi thời gian gấp.","Xác nhận lịch và chuẩn bị cách thay thế trước hạn chót.","thời điểm","Khuyến khích kiểm tra thông tin và phương án dự phòng."],
  ["Người thợ sửa khóa","THUẬN","Ổ khóa kẹt vì bụi lâu ngày\nNgười thợ tra dầu, xoay thật đều\nCửa mở nhờ thợ khéo, kiên nhẫn\nViệc khó tìm đúng cách sẽ xuôi","Kỹ năng phù hợp và sự kiên nhẫn có thể tháo gỡ trở ngại tưởng như bế tắc.","Ổ khóa được tra dầu","Công cụ đúng và hiểu biết giúp lực nhỏ tạo thay đổi.","Đừng tự xử lý nguy hiểm nếu thiếu chuyên môn.","Tìm người có kỹ năng cần thiết thay vì cố làm bằng sức.","giải quyết vấn đề","Tôn trọng chuyên môn và giới hạn năng lực cá nhân."],
  ["Đám mây không mưa","BÌNH","Mây đen trôi qua ngoài cửa biển\nKhông phải lần nào cũng thành mưa\nLo xa giúp mình xem mái ngói\nNhưng đừng trú mãi giữa trời trưa","Chuẩn bị cho khả năng xấu là hữu ích, nhưng sống trong lo sợ liên tục sẽ thu hẹp cuộc sống.","Đám mây trôi xa","Nguy cơ có thể chỉ là một khả năng, không phải kết quả chắc chắn.","Nếu lo âu ảnh hưởng sinh hoạt lâu dài, nên tìm trợ giúp phù hợp.","Ghi điều có thể chuẩn bị và điều nằm ngoài khả năng kiểm soát.","cân bằng","Tránh trấn an tuyệt đối; gợi phân biệt kiểm soát được và không."],
  ["Hạt giống trong tay trẻ","THUẬN","Đứa trẻ nâng hạt bằng hai ngón\nĐất đợi ngoài sân đã xới rồi\nTrao niềm tin kèm theo hướng dẫn\nTự làm mới biết quý công người","Trao cơ hội học hỏi cùng sự hướng dẫn phù hợp giúp người trẻ phát triển trách nhiệm.","Hạt giống trong tay","Niềm tin hiệu quả khi đi với kỹ năng và mức tự chủ tăng dần.","Đừng giao trách nhiệm vượt quá khả năng và độ an toàn.","Giao một việc vừa sức, hướng dẫn cách làm rồi để người học tự thử.","gia đình","Khuyến khích tự chủ có hỗ trợ, không kiểm soát quá mức."],
  ["Lối đi qua chợ đông","CẨN TRỌNG","Chợ đông người gọi mời bốn phía\nTúi bên vai cần giữ thật gần\nLời ngon ngọt chưa thành bằng chứng\nChọn món mình cần, chớ mua nhầm","Nhiều lựa chọn và lời mời có thể gây phân tán; giữ tiêu chí giúp tránh quyết định theo áp lực.","Lối chợ đông","Tiếng ồn bên ngoài dễ lấn át nhu cầu thật của mình.","Không quyết định dưới sức ép thời gian giả tạo.","Viết trước tiêu chí mua/chọn và xin thời gian suy nghĩ.","tài chính","Nhắc tỉnh táo trước bán hàng gây áp lực."],
  ["Cây cầu giữa hai làng","THUẬN","Hai làng góp gỗ làm cầu nhỏ\nBờ cách xa nay bước gần nhau\nKhác tiếng nói nhưng chung lối nước\nCùng giữ nhịp cầu khỏi bạc màu","Hợp tác giữa các nhóm khác nhau có thể tạo lợi ích chung khi trách nhiệm được chia đều.","Cây cầu liên làng","Công trình chung nối những người không nhất thiết giống nhau.","Đừng giả định lợi ích chia đều nếu quyền quyết định không công bằng.","Thống nhất mục tiêu, đóng góp và cách giải quyết bất đồng từ đầu.","quan hệ xã hội","Đề cao công bằng trong hợp tác, không chỉ hòa hợp bề ngoài."],
  ["Chiếc neo thả sâu","BÌNH","Thuyền neo sâu khi trời nổi gió\nChẳng phải sợ xa bến ngày mai\nCó chỗ vững rồi thì đi tiếp\nTự do cần điểm tựa trong đời","Điểm tựa ổn định có thể giúp người hỏi mạo hiểm lành mạnh hơn.","Chiếc neo dưới nước","Sự an toàn nền tảng tạo khả năng khám phá.","Đừng để nhu cầu an toàn giữ mình ở nơi gây hại.","Xác định người, nguồn lực hoặc thói quen giúp mình hồi phục.","cân bằng","Nêu điểm tựa hỗ trợ nhưng không khuyên bám vào môi trường nguy hiểm."],
  ["Cánh đồng sau sương","THUẬN","Sương tan, bờ cỏ hiện đường nhỏ\nNgười đi hôm qua để dấu chân\nSáng nay có thể nhìn thêm hướng\nKinh nghiệm soi đường, chẳng trói chân","Kinh nghiệm trước đây có thể hỗ trợ lựa chọn mới mà không cần lặp lại quá khứ.","Dấu chân sau sương","Ký ức hữu ích khi được dùng làm thông tin, không phải khuôn cứng.","Đừng để thất bại cũ định nghĩa mọi cơ hội mới.","So sánh điều kiện hiện tại với lần trước, ghi cả điểm khác nhau.","trưởng thành","Dùng kinh nghiệm có chọn lọc, tránh khái quát hóa."],
  ["Ngọn nến giữa phòng rộng","BÌNH","Nến nhỏ không soi hết vách xa\nNhưng đủ tìm đôi dép dưới chân\nLàm điều trước mắt cho trọn vẹn\nRồi bước tiếp khi sáng hơn dần","Khi chưa thể giải quyết toàn bộ vấn đề, hãy tập trung vào bước gần nhất có ích.","Ngọn nến nhỏ","Ánh sáng hạn chế vẫn giúp định hướng hành động trước mắt.","Đừng cố giải quyết mọi việc một mình.","Chọn một việc cấp thiết trong hôm nay và nhờ trợ giúp cho phần còn lại.","định hướng","Chia nhỏ công việc và nhận biết khi cần hỗ trợ."],
  ["Người giữ lời hứa nhỏ","THUẬN","Hứa tưới cây, sáng nào cũng nhớ\nChậu nhỏ xanh nhờ những lần đều\nTình thân lớn từ điều giản dị\nĐừng hẹn điều mình chẳng thể theo","Sự chăm sóc bền vững hình thành qua hành động nhỏ được duy trì.","Chậu cây được tưới","Tính nhất quán đem lại cảm giác an toàn và phát triển.","Đừng hứa chỉ để xoa dịu phút hiện tại.","Chọn một hành động nhỏ có thể lặp lại và báo trước khi không làm được.","tình cảm","Coi trọng độ tin cậy và giao tiếp khi kế hoạch thay đổi."],
  ["Mặt hồ có gợn","BÌNH","Mặt hồ gợn vì cành rơi nhẹ\nKhông cần khuấy nước để nhìn sâu\nĐứng yên một lúc, hình sẽ rõ\nBình tĩnh không làm mất điều đau","Sự bình tĩnh giúp suy xét tốt hơn nhưng không phủ nhận cảm xúc hay vấn đề thật.","Gợn sóng trên hồ","Yên lặng có thể làm hình ảnh rõ hơn mà không xóa nguyên nhân.","Đừng buộc mình phải bình thản khi đang bị tổn thương.","Gọi tên cảm xúc rồi chọn người an toàn để chia sẻ.","cân bằng","Tôn trọng cảm xúc, khuyên tìm hỗ trợ khi cần."],
  ["Đường dây qua thung lũng","CẨN TRỌNG","Dây căng bắc qua khe sâu rộng\nMột mối nối yếu, cả đường chùng\nKiểm tra từng điểm trước khi bước\nTin cậy phải đi với thử cùng","Trước khi phụ thuộc vào một người hay hệ thống, cần kiểm tra các điểm dễ hỏng.","Mối nối dây cầu","Độ tin cậy của cả mạng lưới phụ thuộc vào những liên kết cụ thể.","Đừng giao toàn bộ dữ liệu hoặc quyền quyết định cho một điểm duy nhất.","Thử quy trình ở quy mô nhỏ và lập phương án thay thế.","công việc","Khuyến khích kiểm tra điểm lỗi và giảm phụ thuộc đơn lẻ."],
  ["Hạt mưa đầu mùa","THUẬN","Mưa đầu mùa rơi trên đường bụi\nMùi đất dâng lên gọi mầm xanh\nCơ hội mới cần người đón lấy\nBước nhỏ hôm nay mở lối lành","Một cơ hội đang hình thành có thể tiến triển nếu người hỏi chuyển ý định thành hành động đầu tiên.","Mùi đất sau mưa","Tín hiệu mới khơi lại năng lượng và khả năng bắt đầu.","Đừng chờ cảm hứng hoàn hảo mới hành động.","Thực hiện bước đầu trong một giờ hoặc một ngày tới.","khởi đầu","Chuyển hy vọng thành bước hành động cụ thể, không bảo đảm kết quả."],
  ["Chiếc thang dựa tường","CẨN TRỌNG","Thang dựa tường, chân chưa cài chặt\nLeo cao cần người giữ phía sau\nViệc lớn một mình thêm nguy hiểm\nGọi đúng người cùng kiểm tra nào","Mục tiêu lớn cần nguồn lực, hỗ trợ và biện pháp an toàn tương xứng.","Chiếc thang chưa chèn","Nền móng và người hỗ trợ quyết định độ an toàn của bước tiến.","Đừng nhờ người không đủ năng lực cho việc chuyên môn nguy hiểm.","Kiểm tra nguồn lực, kỹ năng và phương án hỗ trợ trước khi bắt đầu.","trách nhiệm","Khuyên phối hợp đúng chuyên môn và chú ý an toàn."],
  ["Mảnh ghép còn thiếu","BÌNH","Bức tranh dừng vì ô còn trống\nĐừng ép miếng khác vào cho vừa\nHỏi lại mẫu hình mình đang ghép\nCó khi thiếu mảnh ở nơi xa","Khi dữ kiện không khớp, người hỏi cần xem lại giả định thay vì ép kết luận theo ý muốn.","Ô trống trong bức ghép","Khoảng trống cho thấy điều chưa biết, không phải lỗi cần che ngay.","Đừng bỏ qua bằng chứng trái với kỳ vọng.","Ghi điều chưa rõ và tìm thông tin có thể kiểm chứng.","tri thức","Khuyến khích nhận diện sự không chắc chắn và cập nhật quan điểm."],
  ["Gánh nhẹ sau chia phần","THUẬN","Gánh chia đôi qua con dốc nhỏ\nVai bớt đau, bước vững hơn nhiều\nNhờ người không làm mình yếu thế\nCùng san phần khó, sức bền theo","Nhận hỗ trợ phù hợp có thể giúp người hỏi tiếp tục mà không phải gánh mọi thứ một mình.","Đòn gánh chia đều","Sự chia sẻ giảm áp lực và tăng khả năng hoàn thành.","Chọn người có thể tin cậy và thống nhất kỳ vọng.","Nêu rõ việc cần giúp, thời gian và phần mình vẫn chịu trách nhiệm.","nghị lực","Khẳng định nhận trợ giúp là năng lực, không phải thất bại."],
  ["Vòng tròn bên bếp lửa","BÌNH","Mỗi người kể một điều chưa nói\nLửa reo, căn bếp bớt xa xôi\nGia đình cần nghe không phán xét\nChậm lời khuyên, hỏi cảm nhận thôi","Không gian lắng nghe an toàn giúp người thân chia sẻ điều khó nói.","Vòng người bên bếp","Sự hiện diện và chú tâm có thể nuôi kết nối.","Đừng ép chia sẻ chuyện riêng khi người kia chưa sẵn sàng.","Hỏi một câu mở và xin phép trước khi đưa lời khuyên.","gia đình","Tôn trọng đồng thuận và quyền riêng tư trong gia đình."],
];

if (rows.length !== 100) throw new Error(`Expected exactly 100 authored entries, found ${rows.length}`);
const records = rows.map(([title, grade, poem, centralMeaning, symbol, symbolMeaning, caution, action, topic, interpretationGuidance], index) => ({
  id: index + 1,
  systemId,
  title,
  poem,
  grade,
  centralMeaning,
  symbols: [symbol],
  symbolicExplanations: [{ symbol, meaning: symbolMeaning }],
  topics: [topic],
  interpretationGuidance,
  cautions: [caution],
  practicalAdvice: [action],
  contentType: "ORIGINAL",
  authoringMethod: "AI_ASSISTED_EDITORIAL_DRAFT",
  contentVersion: datasetVersion,
  reviewStatus: "DRAFT",
}));
const dataset = {
  systemId,
  datasetVersion,
  language: "vi",
  expectedCount: 100,
  status: "DRAFT_NOT_APPROVED",
  sourcePolicy: "ORIGINAL_EDITORIAL_CONTENT_NO_TRADITIONAL_SOURCE_CLAIM",
  sourceReferencePolicy: "The Scribd reference was consulted only for presentation structure; no source poem, translation, grade, interpretation, or commentary is used as dataset content.",
  authorship: { owner: "Tin Lắm Tâm Linh", method: "AI-assisted original editorial drafting; requires human content review", humanApproved: false },
  gradeDefinitions: {
    THUẬN: "Có điều kiện thuận lợi để tiến hành từng bước; không bảo đảm kết quả.",
    BÌNH: "Cần quan sát, trao đổi hoặc chuẩn bị; chưa nghiêng rõ về thuận hay khó.",
    "CẨN TRỌNG": "Nên kiểm tra rủi ro, giới hạn hoặc điều kiện trước khi cam kết.",
  },
  records,
};
const output = path.resolve(__dirname, "../data/xin-xam/tltl-original-100-v1.json");
fs.writeFileSync(output, `${JSON.stringify(dataset, null, 2)}\n`, "utf8");
console.log(`Wrote ${records.length} original editorial drafts to ${output}`);
